# NOTE: Generated By InterfaceTester 5.0.1
# FROM: login.yml
from interfacetester import InterfaceTester, Config, Step, RunRequest


class TestCaseLogin(InterfaceTester):

    config = (
        Config("登录链路（demo）")
        .variables(**{"uid": 1001})
        .base_url("http://127.0.0.1:18080")
    )

    teststeps = [
        Step(
            RunRequest("登录拿 token")
            .post("/api/login")
            .with_headers(**{"Content-Type": "application/json"})
            .with_json({"username": "admin", "password": "123456"})
            .set_timeout(5)
            .extract()
            .with_jmespath("body.data.token", "token")
            .validate()
            .assert_equal("status_code", 200)
            .assert_equal("body.code", 0)
        ),
        Step(
            RunRequest("带 token 查询用户")
            .get("/api/user/info")
            .with_headers(
                **{
                    "Authorization": "Bearer $token",
                    "X-Trace-Id": "${trace_id()}",
                    "X-Uid": "uid-$uid",
                }
            )
            .set_timeout(5)
            .validate()
            .assert_equal("status_code", 200)
            .assert_equal("body.data.username", "admin")
            .assert_equal("body.data.role", "admin")
            .assert_jsonschema_match("body", "schemas/user.json")
        ),
    ]


if __name__ == "__main__":
    TestCaseLogin().test_start()
